import {safeAdImage} from '../shared/ad-images';

/**
 * Institutional carousel media: prefer the administrator-approved creative on
 * the campaign's first slide; use the matching original institutional photo
 * on secondary slides. Disabled means disabled across the entire carousel.
 *
 * Fail closed for arbitrary URLs. <AdImage> handles image load failures and
 * exposes the existing SVG underneath rather than rendering a broken card.
 */
export function selectHousePhotoUrl(input:{
  imageDisabled?:boolean;
  customUrl?:string;
  defaultUrl?:string;
  firstSlide:boolean;
}):string|undefined {
  if(input.imageDisabled===true) return undefined;
  const custom=input.firstSlide?safeAdImage(input.customUrl):undefined;
  return custom??safeAdImage(input.defaultUrl);
}

/** Presentation contracts for read-only backend metrics.
 * Figures are measured, never filled with simulated data.
 */
export type AdminSnapshot={
 publicVisible?:number;jobs?:number;verified?:number;pending?:number;
 campaigns?:number;requests?:number;lastSweep?:string;
};
export type EngineId='A'|'B'|'C'|'D'|'CHATGPT'|'GEMINI';
export type EngineRole='discovery'|'documents';
export type EngineStatus='recent'|'stale'|'unreported'|'error';
export type EngineRow={
 id:EngineId;name:string;role:EngineRole;status:EngineStatus;observedAt:string|null;
 source:string;scope:string;notes:string[];
 counts:{scheduled:number|null;attempted:number|null;useful:number|null;blocked:number|null;
 candidates:number|null;verified:number|null;queued:number|null;
 publishedConfirmed:number|null;processed:number|null};
};
export type DayPoint={day:string;engine:EngineId;measure:'sources_attempted'|'docs_processed';value:number};
export type Telemetry={
 schemaVersion:number;readOnly:boolean;generatedAt:string;engines:EngineRow[];
 rollup:{recent:number;reporting:number;total:number};
 history:DayPoint[];historyComplete:boolean;
 missingOrFailed:EngineId[];warning:string;
};
export type ExecutiveKpi={key:string;label:string;value:string;note:string;accent:string};
export const MAIN_CITIES=[
 'Angol','Collipulli','Ercilla','Lumaco','Los Sauces','Purén','Renaico',
 'Traiguén','Victoria','Mulchén','Negrete','Nacimiento'
] as const;
export function knownCount(value:unknown):string{
 return typeof value==='number'&&Number.isSafeInteger(value)&&value>=0?String(value):'Sin datos';
}
export function percent(part:unknown,total:unknown):number|null {
 return typeof part==='number'&&typeof total==='number'&&
  Number.isSafeInteger(part)&&part>=0&&Number.isSafeInteger(total)&&total>0&&part<=total
    ?Math.round((part/total)*100):null;
}
export function formatRatio(part:unknown,total:unknown):string{
 const p=percent(part,total);
 return p===null?'Sin datos':p+' %';
}
export function executiveKpis(s?:AdminSnapshot,t?:Telemetry|null):ExecutiveKpi[]{
 const d=t?.engines?.find(e=>e.id==='D');
 const a=t?.engines?.find(e=>e.id==='A');
 const readable=d?.counts.attempted!==null&&d?.counts.attempted!==undefined?d:a;
 const ratio=readable?formatRatio(readable.counts.useful,readable.counts.attempted):'Sin datos';
 return [
  {key:'visible',label:'Ofertas públicas',value:knownCount(s?.publicVisible),
   note:'En el catálogo, no nuevas del día',accent:'blue'},
  {key:'readable',label:'Lectura útil · '+(readable?.name||'motores'),value:ratio,
   note:readable?'Fuentes accesibles / intentadas del último ciclo':'Aún sin reporte válido',accent:'teal'},
  {key:'motors',label:'Motores con reporte reciente',
   value:t?knownCount(t.rollup.recent)+' / '+knownCount(t.rollup.total):'Sin datos',
   note:'Actividad observada, no cobertura completa',accent:'violet'},
  {key:'pending',label:'Candidatos pendientes',value:knownCount(s?.pending),
   note:'Conteo interno consultado; no publicados',accent:'amber'},
  {key:'ads',label:'Campañas publicitarias',value:knownCount(s?.campaigns),
   note:'Solicitudes por revisar: '+knownCount(s?.requests),accent:'green'}
 ];
}
export type CityCount={city:string;visible:string;audited:string;expected:string;failed:string};
type Row=Record<string,unknown>;
export function cityCounts(payload:unknown):CityCount[]{
 const record=payload&&typeof payload==='object'&&!Array.isArray(payload)?payload as Record<string,unknown>:{};
 const items=Array.isArray(record.communes)?record.communes:[];
 const byCity=new Map<string,Row>();
 for(const item of items){
  if(!item||typeof item!=='object'||Array.isArray(item))continue;
  const row=item as Row;
  if(typeof row.city==='string'&&MAIN_CITIES.includes(row.city as typeof MAIN_CITIES[number]))byCity.set(row.city,row);
 }
 return MAIN_CITIES.map(city=>{
  const row=byCity.get(city);
  return {city,visible:knownCount(row?.publicJobs),
   audited:knownCount(row?.sourceChecked),expected:knownCount(row?.sourceConfigured),
   failed:knownCount(row?.sourceFailed)};
 });
}
export function chartValues(points:DayPoint[],engine:'A'|'B'|'C'):DayPoint[]{
 return points.filter(p=>p.engine===engine&&
   (engine==='A'?p.measure==='sources_attempted':p.measure==='docs_processed')&&
   /^\d{4}-\d{2}-\d{2}$/.test(p.day)&&Number.isSafeInteger(p.value)&&p.value>=0)
   .sort((a,b)=>a.day.localeCompare(b.day)).slice(-8);
}
export function engineStatus(status:EngineStatus):string{
 return {recent:'Registro reciente',stale:'Sin ejecución reciente',unreported:'Sin reporte',
   error:'Requiere revisión'}[status];
}

import {useEffect,useState} from 'react';
import {api} from '@appdeploy/client';
import {cityCounts,executiveKpis,knownCount,type AdminSnapshot,type Telemetry} from './executive-metrics';
import {ActivityChart,SourceDonut,TerritoryBars,EnginesTable,ExecutiveStatusBar} from './executive-charts';
import './executive-control-center.css';

type TerritoryResult={
 readOnly?:boolean;checkedAt?:string;feedComplete?:boolean;
 sourceAuditComplete?:boolean;communes?:unknown[];
};
function isRecord(value:unknown):value is Record<string,unknown>{
 return value!==null&&typeof value==='object'&&!Array.isArray(value);
}
function isTelemetry(value:unknown):value is Telemetry {
 const r=isRecord(value)?value:{};
 return r.schemaVersion===1&&r.readOnly===true&&Array.isArray(r.engines)&&
   isRecord(r.rollup)&&Array.isArray(r.history);
}
function timeText(value:unknown):string {
 if(typeof value!=='string'||!Number.isFinite(Date.parse(value)))return 'Sin datos';
 return new Date(value).toLocaleString('es-CL',{dateStyle:'short',timeStyle:'short'});
}
export function ExecutiveControlCenter({summary}:{summary?:AdminSnapshot}){
 const [territory,setTerritory]=useState<TerritoryResult|null>(null);
 const [telemetry,setTelemetry]=useState<Telemetry|null>(null);
 const [refresh,setRefresh]=useState(0);
 const [loading,setLoading]=useState(true);
 const [failures,setFailures]=useState<string[]>([]);
 useEffect(()=>{
  let active=true;setLoading(true);
  const urls=['/api/admin/territorial-coverage','/api/admin/ops-telemetry'];
  void Promise.allSettled(urls.map(url=>api.get(url))).then(results=>{
    if(!active)return;
    const problems:string[]=[];
    const first=results[0],second=results[1];
    if(first.status==='fulfilled'&&isRecord(first.value.data)){
      setTerritory(first.value.data as TerritoryResult);
    }else{setTerritory(null);problems.push('cobertura por comuna');}
    if(second.status==='fulfilled'&&isTelemetry(second.value.data)){
      setTelemetry(second.value.data);
    }else{setTelemetry(null);problems.push('telemetría de motores');}
    setFailures(problems);setLoading(false);
  });
  return()=>{active=false;};
 },[refresh]);
 const cards=executiveKpis(summary,telemetry);
 const cities=cityCounts(territory);
 return <section className='tcExecCenter' aria-label='Centro de Control de Trabajo Cerca'>
   <header className='tcExecHero'>
     <div className='tcExecHeroTitle'>
      <span className='tcExecEyebrow'>ADMINISTRACIÓN / INTELIGENCIA OPERATIVA</span>
      <h3>Centro de Control</h3>
      <p>Rastreo, publicaciones y publicidad local, con cifras verificables y trazabilidad.</p>
     </div>
     <div className='tcExecHeroActions'>
      <small>Datos actualizados: {timeText(telemetry?.generatedAt||territory?.checkedAt)}</small>
      <button type='button' onClick={()=>setRefresh(n=>n+1)} disabled={loading}>
       {loading?'Actualizando…':'Actualizar tablero'}
      </button>
     </div>
   </header>
   <div className='tcExecKpis'>
    {cards.map(card=><article key={card.key} className='tcExecKpi' data-accent={card.accent}>
      <span className='tcExecKpiTitle'>{card.label}</span>
      <strong className='tcExecKpiValue'>{card.value}</strong>
      <small>{card.note}</small>
    </article>)}
   </div>
   {failures.length>0&&<p className='tcExecNotice' role='status'>
      Los siguientes informes no respondieron: {failures.join(', ')}. Sus valores aparecen como «Sin datos».
   </p>}
   <ExecutiveStatusBar telemetry={telemetry}/>
   <div className='tcBIChartsTop'>
     <ActivityChart history={telemetry?.history} complete={telemetry?.historyComplete}/>
     <SourceDonut engines={telemetry?.engines}/>
   </div>
   <div className='tcBIChartsBottom'>
     <TerritoryBars cities={cities} feedComplete={territory?.feedComplete}/>
     <div className='tcBIChartCard tcBIManagement'>
      <header className='tcBIChartHead'><div><h4>Control territorial</h4>
       <p>Cobertura de las 12 comunas y estado del proceso.</p></div></header>
      <dl>
       <div><dt>Comunas principales</dt><dd>12</dd></div>
       <div><dt>Catálogo público</dt><dd>{territory?.feedComplete===true?'Completo':
         territory?.feedComplete===false?'Parcial':'Sin datos'}</dd></div>
       <div><dt>Auditoría de fuentes</dt><dd>{territory?.sourceAuditComplete===true?'Consulta completa':
         territory?.sourceAuditComplete===false?'Consulta parcial':'Sin datos'}</dd></div>
       <div><dt>Última revisión territorial</dt><dd>{timeText(territory?.checkedAt)}</dd></div>
      </dl>
      <details className='tcBICityDetails'>
       <summary>Ver cobertura detallada por comuna</summary>
       <div className='tcBITableWrap'><table>
        <thead><tr><th>Comuna</th><th>Ofertas visibles</th><th>Fuentes revisadas</th>
          <th>Fuentes previstas</th><th>Fallidas</th></tr></thead>
        <tbody>{cities.map(r=><tr key={r.city}><th scope='row'>{r.city}</th>
         <td>{r.visible}</td><td>{r.audited}</td><td>{r.expected}</td><td>{r.failed}</td></tr>)}</tbody>
       </table></div>
      </details>
      <p className='tcExecCaution'>«Revisadas» son fuentes con registro de auditoría,
       no necesariamente lecturas útiles ni empleos encontrados.</p>
     </div>
   </div>
   <EnginesTable telemetry={telemetry}/>
   <footer className='tcExecFooter'>
     <strong>Lectura responsable:</strong> el total visible procede del catálogo; las cifras de cada motor
     corresponden a sus ejecuciones y no deben sumarse como nuevas ofertas publicadas. Los datos faltantes
     permanecen explícitos. Panel privado, de solo lectura y sin información personal.
   </footer>
 </section>;
}

